-- #hud

-- .hud-top
.hud-top{position:absolute;top:0;left:0;right:0;height:68px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,12,10,.88),transparent)}
.hud-top{padding:0 16px;height:56px}

-- .objective
.objective{position:absolute;top:99px;left:35px;display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--panel);border-left:2px solid var(--acid);min-width:204px;backdrop-filter:blur(10px)}
.objective-icon{font-size:19px;color:var(--acid)}
.objective small,.objective b{display:block}
.objective b{display:block}
.objective small{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#929b90;margin-bottom:3px}
.objective b{font-weight:500;font-size:12px}
.objective{left:15px;top:72px;min-width:0;padding:8px 10px}
.objective b{font-size:10px}

-- .status-panel
.status-panel{position:absolute;right:35px;top:99px;width:205px;background:var(--panel);border:1px solid #dce5d51c;padding:15px 15px 12px;backdrop-filter:blur(10px)}
.status-panel{right:14px;top:72px;width:165px;padding:11px}

-- .bottom-left
.bottom-left,.bottom-right{position:absolute;bottom:31px;display:flex;align-items:center;gap:9px;color:#b2b9ae;font:9px 'DM Mono',monospace;letter-spacing:.06em}
.bottom-left{left:35px}
.bottom-left i{height:12px;width:1px;background:#647064}
.bottom-left span:last-child{color:#758075}
.bottom-left{left:14px;bottom:17px;font-size:8px}
.bottom-left span:last-child{display:none}

-- .roster
.roster{position:absolute;left:35px;bottom:72px;width:205px;padding:12px 14px;background:var(--panel);backdrop-filter:blur(10px);border:1px solid #dce5d51c}
.roster-label{font:9px 'DM Mono',monospace;letter-spacing:.11em;color:#aab3a7;border-bottom:1px solid #ffffff18;padding-bottom:9px}
.roster-label span{float:right;color:var(--acid)}
.roster-person{display:flex;align-items:center;gap:8px;padding-top:9px;font-size:10px;color:#c5cdc3}
.roster-person small{margin-left:auto;color:#879186;font:8px 'DM Mono',monospace}
.roster{left:14px;bottom:64px;width:165px}
.roster-person{font-size:9px}

-- #mobile-controls
#mobile-controls{position:absolute;inset:auto 0 20px;z-index:6;pointer-events:none}

