function inCabin(x,z){return Math.abs(x)<4.9&&Math.abs(z)<3.95;}
const PLAYER_RADIUS=.34;
function windowOpening(axis,side,along){
 for(const w of windows){
  if(!w.broken)continue;
  const p=w.group.position;
  if(axis==='z'&&side>0&&Math.abs(p.z-4.08)<.2&&Math.abs(along-p.x)<=.775-PLAYER_RADIUS)return true;
  if(axis==='x'&&Math.abs(p.x)>=4.9&&Math.abs(along-p.z)<=.775-PLAYER_RADIUS)return true;
 }
 return false;
}
function blocksCabinWall(axis,from,to,along){
 const r=PLAYER_RADIUS;
 const walls=axis==='x'?[{plane:-5,side:-1},{plane:5,side:1}]:[{plane:-4.04,side:-1},{plane:4.04,side:1}];
 for(const wall of walls){
  const {plane,side}=wall,limit=plane-side*r;
  const crosses=side>0?(from<=limit&&to>limit):(from>=limit&&to<limit);
  if(!crosses)continue;
  let opening=false;
  if(axis==='z'&&side>0&&Math.abs(along)<=1.3-r)opening=true;
  if(windowOpening(axis,side,along))opening=true;
  if(!opening)return limit;
 }
 return to;
}
function clampPlayer(){player.x=THREE.MathUtils.clamp(player.x,-78,78);player.z=THREE.MathUtils.clamp(player.z,-78,78);}

