function beginHeadRip(s){s.root.updateMatrixWorld(true);s.neckWound.visible=true;scene.attach(s.headGroup);const away=new THREE.Vector3(s.x-player.x,0,s.z-player.z).normalize();if(away.lengthSq()<.01)away.set(Math.sin(s.root.rotation.y),0,Math.cos(s.root.rotation.y));const flecks=[];for(let i=0;i<9;i++){const fleck=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.045,6,5),new THREE.MeshBasicMaterial({color:i%2?0x8e1713:0x5d0d0b,transparent:true,opacity:.9}));fleck.position.set(s.x+(Math.random()-.5)*.24,1.58+Math.random()*.2,s.z+(Math.random()-.5)*.24);scene.add(fleck);flecks.push({mesh:fleck,velocity:new THREE.Vector3((Math.random()-.5)*2+away.x,Math.random()*2, (Math.random()-.5)*2+away.z)});}deathEffects.push({survivor:s,head:s.headGroup,flecks,velocity:away.multiplyScalar(2.2).add(new THREE.Vector3(0,3.1,0)),time:0});}
function updateDeathEffects(dt){for(let i=deathEffects.length-1;i>=0;i--){const effect=deathEffects[i];effect.time+=dt;effect.velocity.y-=7.5*dt;effect.head.position.addScaledVector(effect.velocity,dt);effect.head.rotation.x+=dt*4.5;effect.head.rotation.z+=dt*3.2;for(const fleck of effect.flecks){fleck.velocity.y-=8*dt;fleck.mesh.position.addScaledVector(fleck.velocity,dt);fleck.mesh.scale.multiplyScalar(Math.max(0,1-dt*1.6));}if(effect.time>.8)effect.survivor.root.visible=false;if(effect.time>2.8){scene.remove(effect.head);for(const fleck of effect.flecks)scene.remove(fleck.mesh);deathEffects.splice(i,1);}}}
function clearDeathEffects(){for(const effect of deathEffects){scene.remove(effect.head);for(const fleck of effect.flecks)scene.remove(fleck.mesh);effect.survivor.root.add(effect.head);effect.head.position.set(0,1.59,0);effect.head.rotation.set(0,0,0);effect.survivor.neckWound.visible=false;}deathEffects.length=0;}
function capture(s,headRip=false){if(!s||!s.alive)return;s.caught=true;s.alive=false;s.health=0;if(headRip)beginHeadRip(s);else s.root.visible=false;updateRoster();$('#damage-flash').style.opacity='.6';setTimeout(()=>$('#damage-flash').style.opacity='0',220);toast(`${s.name} has been taken`);if(playerRole==='hunter'&&survivors.every(p=>!p.alive||p.caught))finish(true,'THE NIGHT IS YOURS.','Every last voice has gone quiet. Blackwood belongs to you.');}

